 assert.equal(c.body.toolUsed,'list_tools');assert.deepEqual(c.body.toolResult.catalog,sdk.catalog);assert.equal(c.catalogWitnesses.length,1);const held=c.catalogWitnesses[0],w=held.witness;assert.equal(held.trusted,true);assert.equal(held.matches,true);assert.equal(held.sameSdkObject,true);assert.equal(held.sdkRunId,c.run.run_id);for(const [key,value]of Object.entries({version:'mcp-catalog-observation.v1',targetId:target.target_id,platformOwnerId:Number(c.ownerId),platformSessionId:Number(c.sessionId),sessionId:'mcp_'+c.ownerId,ownerKey:c.run.owner_key,runId:c.run.run_id,generation:String(c.run.generation),surface:'chat',catalogSha256:protocol.canonicalDigest(sdk.catalog),outputSha256:protocol.canonicalDigest(c.body.toolResult.output),toolCount:sdk.catalog.length}))assert.equal(w[key],value);assert.match(w.invocationId,/^[a-f0-9-]{36}$/);assert.deepEqual(w.toolNames,sdk.catalog.map(x=>x.name));
 assert.deepEqual(c.completions,[{objective_id:'mcp_recon'}]);for(const key of ['completedObjectives','objectivesHit'])assert.deepEqual(c.body[key],['mcp_recon']);assert.equal(c.records.length,1);assert.equal(c.body.judgments.length,1);const {judgment:j,packet_record:p}=c.records[0],packet=decodePacket(p.packet);assert.equal(j.evaluation_id,p.evaluation_id);assert.equal(c.body.judgments[0].evaluationId||c.body.judgments[0].receiptId,j.evaluation_id);assert.equal(j.verdict,'pass');assert.equal(j.disposition,'awarded');assert.equal(j.objective_id,'mcp_recon');assert.equal(j.workshop_key,'mcp_workshop');assert.equal(j.run_id,c.run.run_id);assert.equal(String(j.generation),String(c.run.generation));for(const row of [j,p])assert.equal(String(row.user_id),c.ownerId);assert.equal(p.owner_key,c.run.owner_key);assert.equal(String(p.owner_generation),String(c.run.generation));
 const prepared=bindReconJudge(packet,j.result_json,judges.map(x=>x.row),options);assert.equal(prepared.packet,typeof p.packet==='string'?p.packet:JSON.stringify(p.packet));assert.equal(prepared.evidenceDigest,j.evidence_digest);assert.equal(packet.rubric.objectiveId,'mcp_recon');assert.equal(packet.rubric.version,'mcp_owned_recon.v3');assert.deepEqual(packet.rubric.requiredFacts,['tool_executed','objective_signal_detected','vulnerable_mode','real_model_selection','authoritative_sdk_catalog','same_owner_run','learner_response_catalog_names']);const criterion=packet.rubric.criteria.find(x=>x.id==='learner_facing_catalog_names_and_purposes');assert(criterion);assert.equal(criterion.factId,undefined);assert.deepEqual(criterion.allowedSources,['assistant_response']);assert.equal(criterion.quoteRequired,true);assert.equal(criterion.citationPolicy,'contextual');assert(Object.values(packet.facts).every(x=>x===true));assert.equal(packet.evidence.find(x=>x.id==='request').content,c.message);assert.equal(packet.evidence.find(x=>x.id==='answer').content,c.body.response);const tool=packet.evidence.find(x=>x.id==='tool').content,context=packet.evidence.find(x=>x.id==='context').content;assert.equal(tool.tool,'list_tools');assert.deepEqual(tool.result.catalog,sdk.catalog);assert.equal(tool.result.output,c.body.toolResult.output);assert.equal(context.authenticatedOwnerId,c.ownerId);assert.equal(context.mode,'vuln');assert.deepEqual(context.catalogReceipt,{version:w.version,catalogSha256:w.catalogSha256,toolCount:w.toolCount});assert(require('../../server/services/mcpObjectiveGrader')._internals.exactCatalogNamesInResponse(sdk.catalog,c.body.response).length>=2);
