function verifyReconRefusal(c,rows,options={}){assert.equal(c.caseId,'recon-named-refusal');assert(rows.every(x=>x.caseId===c.caseId));assert.equal(c.input.evidence.find(x=>x.id==='answer').content,NAMED_REFUSAL);assert.equal(c.input.facts.learner_response_catalog_names,true);assert.equal(c.result.verdict,'fail');bindReconJudge(c.input,c.result,rows,options);assert.deepEqual(c.after,c.before);assert.equal(c.sdkAfter,c.sdkBefore);return {verdict:'fail',judgeCalls:rows.length,durableWrite:false,newSdkCall:false};}
